  root.innerHTML="<main><p class=\"eyebrow\">MODS. GAMES. MEDIA. ONE EVIDENCE CONTRACT.</p><h1>Real cards.<br><em>Nothing quietly missing.</em></h1><p class=\"intro\">Public-source snapshots with original media references. Test image decoding and supported playback without pretending metadata means a complete adapter.</p><div class=\"controls\"><button id=\"load-media\" disabled>Load public image previews</button><button id=\"retry-media\" disabled>Retry failed previews</button><button id=\"export\" disabled>Export test receipt</button><a href=\"https://github.com/Herbertofury/Athena/blob/main/engineering/docs/adapters/README.md\">Platform research</a></div><p class=\"privacy\">Images and players contact their named providers only when loaded. Autoplay is off. No sign-in, private posts or account credentials are included.</p><p id=\"status\" role=\"status\">Loading the versioned public fixture\u2026</p><section class=\"metrics\" aria-label=\"Current test evidence\"><div><span>Source records</span><strong id=\"card-count\">\u2014</strong></div><div><span>Known gallery entries</span><strong id=\"gallery-count\">\u2014</strong></div><div><span>Known video entries</span><strong id=\"video-count\">\u2014</strong></div><div><span>Preview decodes</span><strong id=\"decoded\">0</strong></div></section><p id=\"search-status\" role=\"status\"></p><section id=\"cards\" class=\"cards\" aria-label=\"Real source cards\"></section><section class=\"receipt\"><h2>Measured events</h2><p>Image decode is not video playback. Player-ready is not playing. Missing media stays a failure, not a successful empty card.</p><p id=\"event-mode\"></p><p><button type=\"button\" data-event-mode=\"baseline\">Baseline event view</button> \u00b7 <button type=\"button\" data-event-mode=\"bounded\">Test bounded event view</button></p><button id=\"recover-log\" disabled>Recover retained event display</button><p id=\"log-status\" role=\"status\">No events yet.</p><pre id=\"events\"></pre></section><footer>These are public dated snapshots, not live account sync. All rights remain with the source owners. Media is linked, not relicensed.</footer></main>";const sheet=document.createElement("link");sheet.rel="stylesheet";sheet.href=new URL("./style.css",import.meta.url).href;root.prepend(sheet);setTheme(theme);
  let blockedReceipt=null;const savedReceipt=initialState?.receipt?.schema_version===1 && Array.isArray(initialState.receipt.events)?JSON.parse(JSON.stringify(initialState.receipt)):null;
