const $=id=>root.getElementById(id);
const receipt={schema_version:1,harness:'atlas-real-media-v13-player-ready-deadline',source_module:new URL(import.meta.url).pathname,started_at:new Date().toISOString(),user_agent:navigator.userAgent,source_mode:'dated public snapshots',events:[],acceptance:'not a target-project performance comparison'};
let dataset=null,decoded=0,previewLoader=null,previewBusy=false,mediaReady=false;
const pendingImages=[];
let eventMode=(route.includes('?')?new URLSearchParams(route.slice(route.indexOf('?')+1)).get('event_view'):initialState?.event_view)==='bounded'?'bounded':'baseline';
let eventRecorder=createMediaEventRecorder($('events'),receipt.events,eventMode);
